CREATE TABLE `users` (
  `id` char(36) NOT NULL DEFAULT (uuid()),
  `name` varchar(255) DEFAULT 'User',
  `password_hash` varchar(255) NOT NULL,
  `email` varchar(255) NOT NULL,
  `token` varchar(500) DEFAULT NULL,
